package com.campus.trade.dispute.controller; import com.campus.trade.common.response.Result; import com.campus.trade.dispute.dto.CreateDisputeRequest; import com.campus.trade.dispute.service.DisputeService; import com.campus.trade.dispute.vo.DisputeCreatedVO; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*;
/** 交易双方发起纠纷。管理员处理接口位于 /admin/disputes。 */ @RestController @RequestMapping("/disputes") public class DisputeController {private final DisputeService service;public DisputeController(DisputeService s){service=s;}@PostMapping public Result<DisputeCreatedVO> create(@Valid @RequestBody CreateDisputeRequest r){return Result.ok(service.create(r));}}
